8	/**
9	 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
10	 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
11	 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
12	 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
13	 declaration.
14	
15	 <p>Declarations with no recognizable property, an unclosed function or string (recovered only at a newline, per the
16	 CSS bad-string rule), unbalanced parentheses, or a forbidden or unverifiable external reference are dropped
17	 individually; surrounding safe declarations, other attributes, and the element's text are untouched. An unclosed
18	 comment is itself an unbounded fragment and is dropped, but scanning recovers at the next semicolon so that later
19	 declarations are still parsed independently. Comment text and the contents of ordinary quoted strings are emitted
20	 verbatim but are inert as CSS — a browser removes comments and never tokenizes a function call out of a string — so
21	 a {@code url(...)}-shaped fragment inside either does not by itself trigger a URL check (a quoted string is still
22	 checked when it is the actual argument of a real {@code url()} call). Function names are read with full CSS escape
23	 semantics (hex runs such as {@code \75 rl}, single-character escapes such as a backslash before the letter u, and consecutive
24	 backslashes), so an escaped or differently cased {@code url}, {@code expression}, or equivalent reference is
25	 normalized before the safelist's URL rules are applied. Repeated separators and other degenerate input never throw
26	 and never cause following declarations to be joined into a rejected value.</p>
27	
28	 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
29	 */
30	final class StyleCleaner {
31	    private final Safelist safelist;
32	    private final String tagName;
33	    private final Element el;
34	
35	    private StyleCleaner(Safelist safelist, String tagName, Element el) {
36	        this.safelist = safelist;
37	        this.tagName = tagName;
38	        this.el = el;
39	    }
40	
41	    /**
42	     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
43	     text of every declaration that survives.
44	     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
45	     */
46	    static String clean(Safelist safelist, String tagName, Element el, String value) {
47	        return new StyleCleaner(safelist, tagName, el).clean(value);
48	    }
49	
50	    private String clean(String value) {
51	        StringBuilder out = StringUtil.borrowBuilder();
52	        int length = value.length();
53	        int[] match = parenMatches(value); // index of each parenthesis's mate, or -1 when unmatched
54	        int[] opens = new int[length]; // positions of the currently open parentheses
55	        int segStart = 0;
56	        int parenDepth = 0;
57	        boolean segmentBad = false; // this segment already contains a malformed construct
58	        int i = 0;
59	        while (i < length) {
60	            char c = value.charAt(i);
61	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
62	                i += 2;
63	                continue;
64	            }
65	            if (c == '"' || c == '\'') {
66	                int[] quote = scanQuoted(value, i + 1, c);
67	                if (quote[1] == 1) {
68	                    i = quote[0] + 1;
69	                } else {
70	                    segmentBad = true; // a bad-string token makes only this declaration malformed
71	                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
72	                }
73	                continue;
74	            }
75	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
76	                int close = value.indexOf("*/", i + 2);
77	                if (close < 0) {
78	                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
79	                    // the next ';' so that following declarations stay independently parseable. When no ';' remains,
80	                    // the text before the comment is still validated on its own merits.
81	                    int semi = value.indexOf(';', i + 2);
82	                    if (semi < 0) {
83	                        appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
84	                        segStart = length;
85	                        break;
86	                    }
87	                    segmentBad = true;
88	                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
89	                    continue;
90	                }
91	                i = close + 2;
92	                continue;
93	            }
94	            if (c == '(') {
95	                opens[parenDepth++] = i;
96	            } else if (c == ')') {
97	                if (parenDepth > 0) parenDepth--;
98	                else segmentBad = true; // a stray ')' makes this declaration malformed
99	            } else if (c == ';') {
100	                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0) {
101	                    // the ';' is content of a function that closes later (e.g. an unquoted data: URL); keep scanning
102	                    i++;
103	                    continue;
104	                }
105	                // otherwise end here; a function that never closes only invalidates this declaration
106	                appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
107	                segStart = i + 1;
108	                segmentBad = false;
109	                parenDepth = 0;
110	            }
111	            i++;
112	        }
113	        if (segStart < length) appendSafeDeclaration(value, segStart, length, segmentBad || parenDepth != 0, out);
114	
115	        if (out.length() == 0) {
116	            StringUtil.releaseBuilderVoid(out);
117	            return null;
118	        }
119	        return StringUtil.releaseBuilder(out);
120	    }
121	
122	    /**
123	     Computes the matching parenthesis of every balanced {@code (} and {@code )} in the value, applying the same
124	     * lexical rules (escapes, quoted strings with bad-string recovery, and comments) as the declaration walk. An
125	     * unmatched parenthesis maps to {@code -1}; a single linear pass keeps style cleaning O(n) even when a value
126	     * contains many semicolons nested in functions.
127	     */
128	    private int[] parenMatches(String value) {
129	        int length = value.length();
130	        int[] match = new int[length];
131	        Arrays.fill(match, -1);
132	        int[] stack = new int[length];
133	        int depth = 0;
134	        int i = 0;
135	        while (i < length) {
136	            char c = value.charAt(i);
137	            if (c == '\\') { i += 2; continue; }
138	            if (c == '"' || c == '\'') {
139	                int[] quote = scanQuoted(value, i + 1, c);
140	                i = quote[1] == 0 ? quote[0] : quote[0] + 1; // at the recovered ';', or past the quote/newline
141	                continue;
142	            }
143	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
144	                int close = value.indexOf("*/", i + 2);
145	                if (close < 0) {
146	                    // mirror the declaration walk: an unterminated comment invalidates only its own fragment, and
147	                    // scanning recovers at the next ';'. Any parentheses opened in that dropped fragment are
148	                    // abandoned there, so the nesting depth resets with it.
149	                    int semi = value.indexOf(';', i + 2);
150	                    if (semi < 0) break;
151	                    depth = 0;
152	                    i = semi;
153	                    continue;
154	                }
155	                i = close + 2;
156	                continue;
157	            }
158	            if (c == '(') {
159	                stack[depth++] = i;
160	            } else if (c == ')') {
161	                if (depth > 0) {
162	                    int open = stack[--depth];
163	                    match[open] = i;
164	                    match[i] = open;
165	                }
166	            }
167	            i++;
168	        }
169	        return match;
170	    }
171	
172	    /**
173	     * <ul>
174	     *   <li>state {@code 1}: the closing quote was found at {@code end};</li>
175	     *   <li>state {@code 2}: the string was recovered at the newline at {@code end} (the CSS bad-string rule; later
176	     *       declarations stay independently parseable);</li>
177	     *   <li>state {@code 0}: neither quote nor newline remains; {@code end} is the index of the first semicolon at
178	     *       or after the opening quote (the malformed declaration is cut there), or the value length when none.</li>
179	     * </ul>
180	     */
181	    private int[] scanQuoted(String value, int from, char quote) {
182	        int length = value.length();
183	        int firstSemi = -1;
184	        for (int i = from; i < length; i++) {
185	            char c = value.charAt(i);
186	            if (c == '\\') { i++; continue; }
187	            if (c == quote) return new int[] {i, 1};
188	            if (c == '\n' || c == '\r') return new int[] {i, 2}; // bad-string recovery at a CSS newline
189	            if (c == ';' && firstSemi < 0) firstSemi = i;
190	        }
191	        return new int[] {firstSemi >= 0 ? firstSemi : length, 0};
192	    }
193	
194	    /**
195	     Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}.
196	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
197	     */
198	    private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
199	        if (structurallyBad) return;
200	        int p = skipSpaceAndComments(value, start, end);
201	        if (p < 0) return; // an unterminated leading comment rejects only this declaration
202	        int q = end;
203	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
204	        if (p == q) return; // whitespace-only fragment, e.g. from a duplicated ';'
205	        int nameStart = p;
206	
207	        // an at-rule in a declaration position: only @import is meaningful inline, and its reference must pass
208	        if (value.charAt(p) == '@') {
209	            if (isSafeImportDeclaration(value, p, q)) append(out, value, start, q);
210	            return;
211	        }
212	        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
213	        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
214	        boolean custom = false;
215	        if (value.charAt(p) == '-') {
216	            if (p + 1 < end && value.charAt(p + 1) == '-') {
217	                p += 2;
218	                custom = true;
219	                if (p >= q || !isIdentChar(value.charAt(p))) return; // "--" alone is not a property name
220	                while (p < q && isIdentChar(value.charAt(p))) p++;
221	            } else {
222	                if (p + 1 >= q || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
223	                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
224	            }
225	        }
226	        if (!custom) {
227	            if (p >= q || !isIdentStart(value.charAt(p))) return; // no property name
228	            do { p++; } while (p < q && isIdentChar(value.charAt(p)));
229	        }
230	        int afterName = skipSpaceAndComments(value, p, q); // whitespace/comments may sit between the name and the ':'
231	        if (afterName < 0) return; // an unterminated or unsafe comment in the gap rejects only this declaration
232	        if (afterName >= q || value.charAt(afterName) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
233	        p = afterName + 1; // step past ':'
234	
235	        if (isDangerousProperty(value, nameStart)) return; // known script-entry properties, regardless of value
236	        // a custom property (--name) holds arbitrary free text: its value is scanned as one string, so a colon that is
237	        // not part of a reference (e.g. "--x: https://example.com" or a time such as "12:00"), a stray quote, or an
238	        // at-keyword other than @import is preserved verbatim; only its references decide its fate
239	        boolean safe = custom
240	            ? freeTextIsSafe(value.substring(p, q))
241	            : referencesAreSafe(value, p, q);
242	        if (safe) append(out, value, start, q);
243	    }
244	
245	    /** Appends a surviving declaration, separated from any earlier ones by a single semicolon. */
246	    private void append(StringBuilder out, String value, int from, int to) {
247	        if (out.length() > 0) out.append(';');
248	        out.append(value, from, to);
249	    }
250	
251	    /**
252	     Validates an entire {@code @import} declaration: its leading reference (a quoted URL or a {@code url(...)}) must
253	     * pass the URL rules, and any trailing layer/media/supports conditions must themselves contain no unsafe
254	     * reference.
255	     */
256	    private boolean isSafeImportDeclaration(String value, int at, int end) {
257	        int i = at + 1;
258	        StringBuilder atName = new StringBuilder();
259	        i = scanIdent(value, i, end, atName);
260	        if (!atName.toString().equalsIgnoreCase("import")) return false;
261	        int sep = skipSeparators(value, i, end);
262	        if (sep < 0 || sep >= end) return false;
263	        i = sep;
264	        int afterRef;
265	        char c = value.charAt(i);
266	        if (c == '"' || c == '\'') {
267	            int[] quote = scanQuoted(value, i + 1, c);
268	            if (quote[1] != 1) return false;
269	            if (!safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quote[0])))) return false;
270	            afterRef = quote[0] + 1;
271	        } else if (isIdentStart(c) || c == '-' || c == '\\') {
272	            StringBuilder fnName = new StringBuilder();
273	            int nameEnd = scanIdent(value, i, end, fnName);
274	            int k = skipSeparators(value, nameEnd, end);
275	            if (k < 0 || k >= end || value.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
276	            int argEnd = matchingParen(value, k + 1, end);
277	            if (argEnd < 0 || !isSafeUrlArgument(value, k + 1, argEnd)) return false;
278	            afterRef = argEnd + 1;
279	        } else {
280	            return false;
281	        }
282	        return referencesAreSafe(value, afterRef, end);
283	    }
284	
285	    /**
286	     Advances past CSS whitespace and complete block comments. A comment is inert token separators (a browser removes
287	     it before tokenization), so its text is never inspected for a concealed reference; an unterminated comment is
288	     still an unbounded fragment and yields {@code -1}, rejecting only the declaration that contains it.
289	     */
290	    private int skipSpaceAndComments(String value, int i, int end) {
291	        while (i < end) {
292	            char c = value.charAt(i);
293	            if (isCssSpace(c)) { i++; continue; }
294	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
295	                int close = value.indexOf("*/", i + 2);
296	                if (close < 0 || close >= end) return -1;
297	                i = close + 2;
298	                continue;
299	            }
300	            break;
301	        }
302	        return i;
303	    }
304	
305	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url /**\/ ( ... )}). */
306	    private int skipSeparators(String value, int i, int end) {
307	        return skipSpaceAndComments(value, i, end);
308	    }
309	
310	    /**
311	     Tests whether a comment-only separator (no whitespace) from {@code nameEnd} glues the preceding identifier run
312	     to another identifier run that is itself followed (optionally via separators) by {@code (}. A comment wedged
313	     between two identifier runs ({@code ur/**\/l( ... )} or {@code expr/**\/ession( ... )}) does not join them under
314	     a strict CSS tokenizer, but a lenient engine could read the glued run as a single function token; such a
315	     declaration is rejected rather than risk a split {@code url} or {@code expression} escaping recognition. Real
316	     whitespace keeps the runs distinct tokens, and two bare runs without a following call ({@code a/**\/b}) stay
317	     untouched. The second run is read with full escape semantics so that an escaped continuation such as
318	     {@code ur/**\/\6c( ... )} is just as ambiguous.
319	     */
320	    private boolean commentGluesIdentToCall(String value, int nameEnd, int end) {
321	        int i = nameEnd;
322	        boolean sawComment = false;
323	        while (i < end) {
324	            char c = value.charAt(i);
325	            if (isCssSpace(c)) return false; // real whitespace keeps the two runs distinct tokens
326	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
327	                int close = value.indexOf("*/", i + 2);
328	                if (close < 0 || close > end) return false;
329	                sawComment = true;
330	                i = close + 2;
331	                continue;
332	            }
333	            break; // reached the start of whatever the separator abuts
334	        }
335	        if (!sawComment) return false;
336	        if (i >= end || !(isIdentStart(value.charAt(i)) || value.charAt(i) == '\\'))
337	            return false; // the separator must glue onto another identifier run
338	        StringBuilder glued = new StringBuilder();
339	        int k = scanIdent(value, i, end, glued);
340	        k = skipSeparators(value, k, end);
341	        return k >= 0 && k < end && value.charAt(k) == '(';
342	    }
343	
344	    /**
345	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
346	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}. The name is
347	     * the plain identifier run starting at {@code nameStart}; a comment appended to the name cannot change the
348	     * comparison.
349	     */
350	    private boolean isDangerousProperty(String value, int nameStart) {
351	        int p = nameStart;
352	        while (p < value.length() && isIdentChar(value.charAt(p))) p++;
353	        String name = value.substring(nameStart, p);
354	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
355	    }
356	
357	    /**
358	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
359	     recognized exactly as in declaration splitting. Block comments and the contents of ordinary quoted strings are
360	     inert token separators (their text is emitted verbatim but never fetched or tokenized as a call); a quoted
361	     string is still checked when it is the actual argument of a {@code url()} call. Every {@code url(...)}
362	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is read with full CSS
363	     escape semantics, so a hex or character escape, consecutive backslashes, or a case change in the function name
364	     ({@code \75 rl(...)}, a backslash-escaped {@code URL}, {@code \65 xpression(...)}) reaches the same decision as the plain
365	     spelling. Unbalanced parentheses, an unterminated string or comment, or any failed reference check rejects the
366	     declaration.
367	     */
368	    private boolean referencesAreSafe(String value, int start, int end) {
369	        int parenDepth = 0;
370	        int i = start;
371	        while (i < end) {
372	            char c = value.charAt(i);
373	            if (c == '"' || c == '\'') {
374	                int[] quote = scanQuoted(value, i + 1, c);
375	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
376	                // an identifier run glued directly to the string and followed by a call (e.g. u"rl"(...)) is a
377	                // syntax error a strict browser discards but a lenient one could read as one escaped function name
378	                if (stringGluesIdentToCall(value, i, quote[0], end)) return false;
379	                // ordinary string content is inert: it is never fetched as a reference (a quoted url() argument is
380	                // checked separately by isSafeUrlArgument)
381	                i = quote[0] + 1;
382	                continue;
383	            }
384	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
385	                int close = value.indexOf("*/", i + 2);
386	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
387	                i = close + 2; // comment text is inert token separators, never a concealed declaration or call
388	                continue;
389	            }
390	            if (c == '(') { parenDepth++; i++; continue; }
391	            if (c == ')') {
392	                if (parenDepth == 0) return false; // unmatched ')'
393	                parenDepth--;
394	                i++;
395	                continue;
396	            }
397	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
398	            if (isIdentStart(c) || c == '-' || c == '\\') {
399	                StringBuilder decoded = new StringBuilder();
400	                int nameEnd = scanIdent(value, i, end, decoded);
401	                String fnName = decoded.toString();
402	                int j = skipSeparators(value, nameEnd, end);
403	                if (j < 0) return false; // an unterminated comment after the name rejects the declaration
404	                if (commentGluesIdentToCall(value, nameEnd, end)) return false; // e.g. ur/**/l(...)
405	                if (j < end && value.charAt(j) == '(') {
406	                    int argEnd = matchingParen(value, j + 1, end);
407	                    if (argEnd < 0) return false;
408	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
409	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
410	                    if (!isPlainName(fnName)) return false;
411	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
412	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
413	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
414	                    continue;
415	                }
416	                i = nameEnd;
417	                continue;
418	            }
419	            i++;
420	        }
421	        return parenDepth == 0;
422	    }
423	
424	    /** Tests that a function name is a plain identifier, with no escape that decoded to punctuation or whitespace. */
425	    private static boolean isPlainName(String name) {
426	        int length = name.length();
427	        if (length == 0) return false;
428	        for (int k = 0; k < length; k++) {
429	            char c = name.charAt(k);
430	            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
431	                || (c >= '0' && c <= '9') || c == '-' || c == '_';
432	            if (!ok) return false;
433	        }
434	        return true;
435	    }
436	
437	    /**
438	     Reads a CSS identifier token starting at {@code from} with full escape semantics: plain identifier characters
439	     (including a leading run of dashes), single-character escapes (a backslash before any character such as u or '(', or a doubled
440	     {@code \\}), and hex escapes ({@code \75}, up to six hex digits) together with the single whitespace
441	     delimiter that may follow one ({@code \75 rl} is therefore one token, exactly as a browser reads it). The
442	     decoded code points are appended to {@code decoded}, and the index just past the token is returned. The decoded
443	     form is what a function name is compared against, so a hex-escaped, character-escaped, doubled-backslash, or
444	     differently cased {@code url} or {@code expression} cannot hide from the reference checks.
445	     */
446	    private int scanIdent(String value, int from, int end, StringBuilder decoded) {
447	        int i = from;
448	        while (i < end) {
449	            char c = value.charAt(i);
450	            if (c == '\\') {
451	                int[] escape = consumeEscape(value, i, end);
452	                if (escape[1] >= 0) decoded.appendCodePoint(escape[1]);
453	                i = escape[0];
454	                continue;
455	            }
456	            if (isIdentChar(c)) { decoded.append(c); i++; continue; }
457	            break;
458	        }
459	        return i;
460	    }
461	
462	    /**
463	     Consumes one CSS escape sequence beginning at the backslash {@code i}. Returns {@code [next, codePoint]}:
464	     {@code next} is the index past the escape (including the single whitespace delimiter a hex run may carry, a
465	     CRLF pair counting as one delimiter), and {@code codePoint} is the decoded code point. Per the CSS spec a NUL,
466	     surrogate, or out-of-range value becomes U+FFFD; a lone trailing backslash has no escape ({@code codePoint} is
467	     {@code -1}) and is left to the caller as a stray character.
468	     */
469	    private static int[] consumeEscape(String value, int i, int end) {
470	        if (i + 1 >= end) return new int[] {end, -1};
471	        char next = value.charAt(i + 1);
472	        if (isHex(next)) {
473	            int h = i + 1;
474	            int e = h;
475	            while (e < end && e - h < 6 && isHex(value.charAt(e))) e++;
476	            int code = Integer.parseInt(value.substring(h, e), 16);
477	            int after = e;
478	            if (after < end && isCssSpace(value.charAt(after))) {
479	                after++; // the single delimiter whitespace is part of the hex escape
480	                if (after - e == 2 && value.charAt(e) == '\r' && after < end && value.charAt(after) == '\n') after++;
481	            }
482	            if (code == 0 || code > Character.MAX_CODE_POINT
483	                || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
484	                code = 0xFFFD;
485	            return new int[] {after, code};
486	        }
487	        return new int[] {i + 2, next};
488	    }
489	
490	    /**
491	     Applies the same reference rules to text that is not itself parsed as declarations — the free-form value of a
492	     custom property. As in an ordinary value, quoted strings and comments are inert token separators (a fake call
493	     written inside either never fetches), while every real {@code url(...)} (its name possibly hex- or
494	     character-escaped), {@code @import}, and the legacy {@code expression(...)} function is normalized and checked.
495	     */
496	    private boolean freeTextIsSafe(String text) {
497	        int end = text.length();
498	        int i = 0;
499	        while (i < end) {
500	            char c = text.charAt(i);
501	            if (c == '"' || c == '\'') {
502	                int[] quote = scanQuoted(text, i + 1, c);
503	                if (quote[1] != 1) return false;
504	                if (stringGluesIdentToCall(text, i, quote[0], end)) return false; // e.g. "u"rl(...) or ur"l"(...)
505	                i = quote[0] + 1;
506	                continue;
507	            }
508	            if (c == '/' && i + 1 < end && text.charAt(i + 1) == '*') {
509	                int close = text.indexOf("*/", i + 2);
510	                if (close < 0) return false;
511	                i = close + 2;
512	                continue;
513	            }
514	            if (c == '@') {
515	                StringBuilder atName = new StringBuilder();
516	                int nameEnd = scanIdent(text, i + 1, end, atName);
517	                if (atName.toString().equalsIgnoreCase("import") && !freeTextImportIsSafe(text, nameEnd, end))
518	                    return false;
519	                i = nameEnd > i + 1 ? nameEnd : i + 1;
520	                continue;
521	            }
522	            if (isIdentStart(c) || c == '-' || c == '\\') {
523	                StringBuilder decoded = new StringBuilder();
524	                int nameEnd = scanIdent(text, i, end, decoded);
525	                int j = skipSeparators(text, nameEnd, end);
526	                if (j < 0) return false;
527	                if (commentGluesIdentToCall(text, nameEnd, end)) return false; // e.g. ur/**/l(...)
528	                if (j < end && text.charAt(j) == '(') {
529	                    String fnName = decoded.toString();
530	                    int argEnd = matchingParen(text, j + 1, end);
531	                    if (argEnd < 0) return false;
532	                    if (!isPlainName(fnName)) return false;
533	                    if (fnName.equalsIgnoreCase("expression")) return false;
534	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(text, j + 1, argEnd)) return false;
535	                    i = j; // resume at '(' so a nested url()/expression() in the arguments is also checked
536	                    continue;
537	                }
538	                i = nameEnd;
539	                continue;
540	            }
541	            i++;
542	        }
543	        return true;
544	    }
545	
546	    /**
547	     Tests whether a quoted string at {@code [open, close]} is glued without whitespace to identifier runs on
548	     either side and followed by a call: {@code "u"rl(...)}, {@code ur"l"(...)}, or {@code u"rl"(...)}. Such
549	     token sequences are value syntax errors a strict browser discards, but a lenient engine could read the glued
550	     runs as one escaped {@code url} or {@code expression} call, so the declaration is rejected rather than risk a
551	     split name escaping recognition. The adjacent runs are read with full escape semantics. Ordinary tokens
552	     separated from the string by whitespace (such as a real {@code url(...)} later in the value) are unaffected.
553	     */
554	    private boolean stringGluesIdentToCall(String value, int open, int close, int end) {
555	        boolean gluedBefore = open > 0 && isIdentChar(value.charAt(open - 1));
556	        int after = close + 1;
557	        boolean gluedAfter = after < end && (isIdentStart(value.charAt(after)) || value.charAt(after) == '\\');
558	        if (!gluedBefore && !gluedAfter) return false;
559	        int k = after;
560	        if (gluedAfter) {
561	            StringBuilder ignored = new StringBuilder();
562	            k = scanIdent(value, k, end, ignored);
563	        }
564	        k = skipSeparators(value, k, end);
565	        return k >= 0 && k < end && value.charAt(k) == '(';
566	    }
567	
568	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
569	    private boolean freeTextImportIsSafe(String text, int from, int end) {
570	        int i = skipSeparators(text, from, end);
571	        if (i < 0) return false;
572	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
573	        char c = text.charAt(i);
574	        if (c == '"' || c == '\'') {
575	            int[] quote = scanQuoted(text, i + 1, c);
576	            if (quote[1] != 1) return false;
577	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
578	        }
579	        if (isIdentStart(c) || c == '-' || c == '\\') {
580	            StringBuilder fnName = new StringBuilder();
581	            int nameEnd = scanIdent(text, i, end, fnName);
582	            int k = skipSeparators(text, nameEnd, end);
583	            if (k < 0 || k >= end || text.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
584	            int argEnd = matchingParen(text, k + 1, end);
585	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
586	        }
587	        return false;
588	    }
589	
590	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
591	    private boolean isSafeUrlArgument(String value, int from, int end) {
592	        int i = from;
593	        while (i < end && isCssSpace(value.charAt(i))) i++;
594	        int j = end;
595	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
596	        if (i == j) return false; // url() with no reference
597	
598	        char first = value.charAt(i);
599	        String raw;
600	        if (first == '"' || first == '\'') {
601	            int[] quote = scanQuoted(value, i + 1, first);
602	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
603	            raw = value.substring(i + 1, quote[0]);
604	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
605	                char c = raw.charAt(k);
606	                if (c == '\\') { k++; continue; }
607	                if (c == first) return false;
608	            }
609	        } else {
610	            // an unquoted URL token is a single run: a bare quote or whitespace is a syntax error, not part of the
611	            // URL. Whitespace that is the delimiter of a hex escape (or a whitespace character itself escaped) is
612	            // part of the escape and so stays in the run, exactly as a browser reads it.
613	            int k = i;
614	            while (k < j) {
615	                char c = value.charAt(k);
616	                if (c == '\\') {
617	                    int[] escape = consumeEscape(value, k, j);
618	                    if (escape[1] < 0) return false; // a lone trailing backslash is no URL token
619	                    k = escape[0];
620	                    continue;
621	                }
622	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
623	                k++;
624	            }
625	            raw = value.substring(i, j);
626	        }
627	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
628	    }
629	
630	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
631	    private int matchingParen(String value, int from, int end) {
632	        int depth = 1;
633	        int i = from;
634	        while (i < end) {
635	            char c = value.charAt(i);
636	            if (c == '\\') { i += 2; continue; }
637	            if (c == '"' || c == '\'') {
638	                int[] quote = scanQuoted(value, i + 1, c);
639	                if (quote[1] != 1) return -1;
640	                i = quote[0] + 1;
641	                continue;
642	            }
643	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
644	                int close = value.indexOf("*/", i + 2);
645	                if (close < 0 || close >= end) return -1; // an unterminated comment leaves the function unclosed
646	                i = close + 2;
647	                continue;
648	            }
649	            if (c == '(') depth++;
650	            else if (c == ')') { depth--; if (depth == 0) return i; }
651	            i++;
652	        }
653	        return -1;
654	    }
655	
656	    /**
657	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
658	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
659	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
660	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
661	     CSS requirement to replace it.
662	     */
663	    static String unescape(String value) {
664	        if (value.indexOf('\\') == -1) return value;
665	        int length = value.length();
666	        StringBuilder sb = null;
667	        int i = 0;
668	        while (i < length) {
669	            char c = value.charAt(i);
670	            if (c == '\\' && i + 1 < length) {
671	                if (sb == null) {
672	                    sb = new StringBuilder(length);
673	                    sb.append(value, 0, i);
674	                }
675	                int h = i + 1;
676	                int hexEnd = h;
677	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
678	                if (hexEnd > h) {
679	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
680	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
681	                    // per the CSS spec, NUL, surrogates, and values above the Unicode range become U+FFFD
682	                    if (code == 0 || code > Character.MAX_CODE_POINT
683	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
684	                        code = 0xFFFD;
685	                    sb.appendCodePoint(code);
686	                    i = hexEnd;
687	                } else {
688	                    sb.append(value.charAt(i + 1));
689	                    i += 2;
690	                }
691	                continue;
692	            }
693	            if (sb != null) sb.append(c);
694	            i++;
695	        }
696	        return sb != null ? sb.toString() : value;
697	    }
698	
699	    private static boolean isCssSpace(char c) {
700	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
701	    }
702	
703	    private static boolean isHex(char c) {
704	        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
705	    }
706	
707	    private static boolean isIdentStart(char c) {
708	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
709	    }
710	
711	    private static boolean isIdentChar(char c) {
712	        return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-';
713	    }
714	}
