import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Element;

/**
 Sanitizes the text of an allowed {@code <style>} element, rule by rule. Like {@link StyleCleaner} for an inline
 {@code style} attribute, this is a small hand scanner rather than a full CSS parser: the stylesheet is split into
 statements and qualified rules on top-level braces and semicolons while tracking the actual nesting of quoted
 strings, block comments, and CSS backslash escapes, so punctuation inside a selector or a value
 ({@code a[href="x}y"]}, {@code content: "{"}) cannot end a rule early.

 <p>Each rule is treated independently and emitted in original order. Plain selectors, declaration and
 custom-property names, numbers, colors, and fonts keep their original text; an {@code @import} reference, a
 {@code url(...)} (including one nested inside another function), and the legacy {@code expression(...)} function are
 CSS-unescaped and checked against the protocols configured for the {@code style} tag, reusing exactly the
 inline-style rules in {@link StyleCleaner}. A failed check removes only the declaration or import that owns it,
 never the rule's other content. A rule whose block cannot be bounded (an unclosed string, comment, or brace), a
 dangling fragment, or a reference that cannot be resolved is discarded, while a later rule whose boundary is
 certain is still processed; a fake reference written inside a comment or a quoted string is inert and is never
 checked. No orphaned separator or empty rule is emitted, and when every rule is rejected the whole {@code <style>}
 element is removed by the caller.</p>

 <p>The cleaner is stateless and thread-safe; all per-sheet state is local to the {@link #clean} call.</p>
 */
final class StyleElementCleaner {
    private final StyleCleaner css; // shares the inline-style reference, escape, and declaration rules

    private StyleElementCleaner(Safelist safelist, Element el) {
        this.css = StyleCleaner.forStyleElement(safelist, el);
    }

    /**
     Cleans the raw text of one {@code <style>} element.
     @return the cleaned stylesheet text, or {@code null} when no rule survives (the element is then removed)
     */
    static String clean(Safelist safelist, Element el, String sheet) {
        return new StyleElementCleaner(safelist, el).cleanSheet(sheet);
    }

    private String cleanSheet(String sheet) {
        StringBuilder out = StringUtil.borrowBuilder();
        processFragment(sheet, 0, sheet.length(), out);
        if (out.length() == 0) {
            StringUtil.releaseBuilderVoid(out);
            return null;
        }
        return StringUtil.releaseBuilder(out);
    }

    /**
     Processes the rules and statements in {@code s[from, to)} into {@code out}, appending only surviving items.
     @return {@code true} when at least one item was appended
     */
    private boolean processFragment(String s, int from, int to, StringBuilder out) {
        boolean emitted = false;
        int i = from;
        while (i < to) {
            int[] prelude = scanPrelude(s, i, to);
            int pos = prelude[0];
            int state = prelude[1];
            boolean malformed = prelude[2] == 1;

            if (state == 1) { // an opening brace: a qualified rule or an at-rule with a block
                int open = pos;
                int close = findBlockEnd(s, open + 1, to);
                if (close < 0) break; // an unbounded block swallows the rest of this fragment
                if (!malformed) {
                    String rule = buildRule(s, i, open, open + 1, close);
                    if (rule != null) { out.append(rule); emitted = true; }
                }
                i = close + 1;
                continue;
            }
            if (state == 2) { // a top-level statement terminated by ';'
                if (!malformed) {
                    String statement = buildStatement(s, i, pos);
                    if (statement != null) { out.append(statement); emitted = true; }
                }
                i = pos + 1;
                continue;
            }
            if (state == 3) { i = pos + 1; continue; } // a stray '}': drop just it
            break; // state 0: end of fragment; any trailing text is an unbounded fragment and is dropped
        }
        return emitted;
    }

    /**
     Builds one complete rule: validates the prelude {@code [ruleStart, open)} (selectors fetch nothing, but a
     smuggled reference is still checked) and cleans its block {@code [bodyStart, bodyEnd)}. A block that contains a
     nested rule is processed recursively; otherwise it is a declaration block cleaned declaration by declaration.
     @return the normalized rule text, or {@code null} when it must be dropped (an unsafe prelude or an empty body)
     */
    private String buildRule(String s, int ruleStart, int open, int bodyStart, int bodyEnd) {
        String prelude = s.substring(ruleStart, open).trim();
        if (prelude.isEmpty()) return null; // a block with no selector/header
        if (!css.preludeIsSafe(prelude)) return null;

        String body;
        if (containsNestedBlock(s, bodyStart, bodyEnd)) {
            StringBuilder inner = StringUtil.borrowBuilder();
            boolean kept = processFragment(s, bodyStart, bodyEnd, inner);
            body = kept ? StringUtil.releaseBuilder(inner) : null;
        } else {
            body = css.cleanDeclarations(s.substring(bodyStart, bodyEnd));
        }
        if (body == null || body.isEmpty()) return null; // no empty rule survives
        return prelude + "{" + body + "}";
    }

    /**
     Builds a top-level, semicolon-terminated statement. An {@code @import} is kept only when its leading reference
     and any trailing conditions pass the URL rules; another at-rule statement ({@code @namespace}, {@code @charset},
     …) is kept when it carries no unsafe reference; a bare declaration outside a rule is invalid CSS and is
     dropped.
     */
    private String buildStatement(String s, int start, int semi) {
        int p = start;
        while (p < semi && StyleCleaner.isCssSpace(s.charAt(p))) p++;
        if (p >= semi) return null; // whitespace-only fragment, e.g. from a duplicated ';'
        String text = s.substring(start, semi).trim();
        if (s.charAt(p) != '@') return null; // a loose declaration is not a stylesheet statement
        if (css.isImportAtRule(s, p, semi))
            return css.isSafeImportDeclaration(s, p, semi) ? text + ";" : null;
        return css.preludeIsSafe(s.substring(p, semi)) ? text + ";" : null;
    }

    /**
     Tests whether a block body itself contains a nested qualified rule (a top-level opening brace), which makes it a
     rule container (e.g. {@code @media}, {@code @supports}, {@code @keyframes}) rather than a declaration block
     ({@code @font-face}, {@code @page}, an ordinary selector).
     */
    private boolean containsNestedBlock(String s, int from, int to) {
        int i = from;
        while (i < to) {
            char c = s.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = StyleCleaner.scanQuoted(s, i + 1, c);
                i = quote[1] == 0 ? quote[0] : quote[0] + 1;
                continue;
            }
            if (c == '/' && i + 1 < to && s.charAt(i + 1) == '*') {
                int close = s.indexOf("*/", i + 2);
                if (close < 0) return false; // an unbounded comment cannot introduce a later rule
                i = close + 2;
                continue;
            }
            if (c == '{') return true;
            i++;
        }
        return false;
    }

    /**
     Scans a prelude (selector list or at-rule header) beginning at {@code from} up to the start of its block or
     statement terminator, honoring strings, comments, and escapes. Returns {@code [position, state, malformed]}:
     <ul>
       <li>state {@code 1}: an opening brace at {@code position};</li>
       <li>state {@code 2}: a top-level semicolon at {@code position};</li>
       <li>state {@code 3}: a stray closing brace at {@code position};</li>
       <li>state {@code 0}: the fragment ended with neither ({@code position} is its end).</li>
     </ul>
     An unclosed string is recovered at the next newline (the CSS bad-string rule), and an unclosed string with no
     newline or an unclosed comment is bounded at the next structural character; such a prelude is flagged
     {@code malformed}, so its fragment is dropped while scanning resumes at that boundary.
     */
    private int[] scanPrelude(String s, int from, int to) {
        int i = from;
        while (i < to) {
            char c = s.charAt(i);
            if (c == '\\') { i += (i + 1 < to) ? 2 : 1; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = StyleCleaner.scanQuoted(s, i + 1, c);
                if (quote[1] == 1 || quote[1] == 2) { i = quote[0] + 1; continue; }
                int boundary = quote[0] < to ? quote[0] : to;
                return new int[] {boundary, boundary < to ? boundaryState(s, boundary) : 0, 1};
            }
            if (c == '/' && i + 1 < to && s.charAt(i + 1) == '*') {
                int close = s.indexOf("*/", i + 2);
                if (close >= 0 && close < to) { i = close + 2; continue; }
                int boundary = nextBoundary(s, i + 2, to);
                return new int[] {boundary, boundary >= 0 ? boundaryState(s, boundary) : 0, 1};
            }
            if (c == '{') return new int[] {i, 1, 0};
            if (c == ';') return new int[] {i, 2, 0};
            if (c == '}') return new int[] {i, 3, 0};
            i++;
        }
        return new int[] {to, 0, 0};
    }

    private static int boundaryState(String s, int idx) {
        char c = s.charAt(idx);
        if (c == '{') return 1;
        if (c == ';') return 2;
        return 3; // '}'
    }

    private static int nextBoundary(String s, int from, int to) {
        for (int i = from; i < to; i++) {
            char c = s.charAt(i);
            if (c == '{' || c == ';' || c == '}') return i;
        }
        return -1;
    }

    /**
     Finds the brace closing the block whose opening brace is just before {@code from}, balancing nested braces and
     applying string, comment, and escape lexical rules (a brace inside either is inert). Parentheses are ordinary
     characters here; quotes (such as the quoted argument of a {@code url(...)}) are still skipped.
     @return the index of the matching {@code }}, or {@code -1} when the block never closes
     */
    private int findBlockEnd(String s, int from, int to) {
        int depth = 1;
        int i = from;
        while (i < to) {
            char c = s.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = StyleCleaner.scanQuoted(s, i + 1, c);
                if (quote[1] == 1 || quote[1] == 2) { i = quote[0] + 1; continue; }
                return -1; // an unterminated string leaves the block unbounded
            }
            if (c == '/' && i + 1 < to && s.charAt(i + 1) == '*') {
                int close = s.indexOf("*/", i + 2);
                if (close < 0 || close >= to) return -1; // an unterminated comment leaves the block unbounded
                i = close + 2;
                continue;
            }
            if (c == '{') depth++;
            else if (c == '}') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }
}
